// Load notice template, hash it, and prepare per-custodian email payloads.
const fs = require('fs');
const crypto = require('crypto');

const trigger = $('Issue Trigger').item.json;
const custodians = $input.all().map(r => r.json);
const templatePath = trigger.notice_template_path;
const template = fs.readFileSync(templatePath, 'utf8');
const templateSha = crypto.createHash('sha256').update(template).digest('hex').slice(0, 16);

const out = custodians.map(c => {
  const ackToken = crypto.randomBytes(16).toString('hex');
  const ackUrl = `${$env.ACK_BASE_URL}/ack/${trigger.hold_id}/${c.custodian_id}/${ackToken}`;
  const personalized = template
    .replace(/\{\{custodian_name\}\}/g, c.full_name)
    .replace(/\{\{matter_id\}\}/g, trigger.matter_id)
    .replace(/\{\{hold_id\}\}/g, trigger.hold_id)
    .replace(/\{\{ack_url\}\}/g, ackUrl);

  return {
    json: {
      hold_id: trigger.hold_id,
      matter_id: trigger.matter_id,
      custodian_id: c.custodian_id,
      custodian_email: c.email,
      custodian_slack_id: c.slack_user_id,
      manager_email: c.manager_email,
      template_sha: templateSha,
      ack_token: ackToken,
      ack_url: ackUrl,
      personalized_text: personalized,
      issued_at: new Date().toISOString(),
    }
  };
});

return out;

